/bin/zsh -lc "cat > tb.sv <<'EOF'
"'`timescale 1ns/1ps
module tb;
  reg clk=0;
  reg rst_n=1;
  reg write_en=0;
  reg [7:0] write_addr=0;
  reg [3:0] write_data=0;
  reg read_en=0;
  reg [7:0] read_addr=0;
  wire [3:0] read_data;

  TopModule dut(
    .clk(clk), .rst_n(rst_n),
    .write_en(write_en), .write_addr(write_addr), .write_data(write_data),
    .read_en(read_en), .read_addr(read_addr), .read_data(read_data)
  );

  always #5 clk = ~clk;

  initial begin
    $display("start");
    rst_n = 0;
    #2;
    rst_n = 1;
    @(posedge clk);
    write_en <= 1; write_addr <= 8'"'d2; write_data <= 4'hA;
    @(posedge clk);
    write_en <= 0;
    read_en <= 1; read_addr <= 8'd2;
    @(posedge clk);
    "'$display("read_data=%h expected=A", read_data);
    read_addr <= 8'"'d130;
    @(posedge clk);
    "'$display("read_data@130=%h", read_data);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -Wall -o simv TopModule.sv tb.sv && vvp simv'

