/bin/zsh -lc "cat > tb.sv <<'EOF'
"'`timescale 1ns/1ps
module tb;
  reg clk=0;
  reg rst_n=1;
  reg write_en=0;
  reg [7:0] write_addr=0;
  reg [3:0] write_data=0;
  reg read_en=0;
  reg [7:0] read_addr=0;
  wire [3:0] read_data;

  TopModule dut(
    .clk(clk), .rst_n(rst_n),
    .write_en(write_en), .write_addr(write_addr), .write_data(write_data),
    .read_en(read_en), .read_addr(read_addr), .read_data(read_data)
  );

  always #5 clk = ~clk;

  task check;
    input [255:0] name;
    input [3:0] expected;
    begin
      #1;
      if (read_data !== expected) begin
        $display("FAIL %0s got=%h expected=%h", name, read_data, expected);
        $finish(1);
      end else begin
        $display("PASS %0s got=%h", name, read_data);
      end
    end
  endtask

  initial begin
    rst_n = 0;
    #2;
    if (read_data !== 4'"'h0) begin
      "'$display("FAIL reset read_data=%h", read_data);
      $finish(1);
    end

    rst_n = 1;
    @(posedge clk);
    read_en <= 1; read_addr <= 8'"'d2;
    @(posedge clk); check(\"initial zero\", 4'h0);

    write_en <= 1; write_addr <= 8'd2; write_data <= 4'hA;
    @(posedge clk);
    write_en <= 0;
    read_addr <= 8'd2;
    @(posedge clk); check(\"read written value\", 4'hA);

    write_en <= 1; write_addr <= 8'd130; write_data <= 4'h5;
    @(posedge clk);
    write_en <= 0;
    read_addr <= 8'd2;
    @(posedge clk); check(\"address wraps to depth-8 RAM\", 4'h5);

    "'$display("PASS all checks");
    $finish;
  end
endmodule
EOF
iverilog -g2012 -Wall -o simv TopModule.sv tb.sv && vvp simv'

